"""SEO 服务测试"""
import pytest
from unittest.mock import MagicMock, patch
from datetime import datetime, timezone


class TestSitemapGenerator:
    """站点地图生成器测试"""

    def test_add_page(self):
        """测试添加页面"""
        from app.services.seo import SitemapGenerator

        generator = SitemapGenerator()
        generator.add_page("/test", "weekly", 0.5)

        assert len(generator._pages) == 1
        assert generator._pages[0]["loc"] == "https://baixing-law.com/test"

    def test_add_page_with_custom_lastmod(self):
        """测试添加页面（自定义时间）"""
        from app.services.seo import SitemapGenerator

        generator = SitemapGenerator()
        generator.add_page("/test", "daily", 0.8, "2024-01-01")

        assert generator._pages[0]["lastmod"] == "2024-01-01"

    def test_generate_sitemap_xml(self):
        """测试生成站点地图 XML"""
        from app.services.seo import SitemapGenerator

        generator = SitemapGenerator()
        generator.add_page("/page1", "weekly", 0.5)
        generator.add_page("/page2", "daily", 0.8)

        xml = generator.generate_sitemap_xml()

        assert '<?xml version="1.0"' in xml
        assert "https://baixing-law.com/page1" in xml
        assert "https://baixing-law.com/page2" in xml
        assert "<urlset" in xml

    def test_generate_sitemap_index(self):
        """测试生成站点地图索引"""
        from app.services.seo import SitemapGenerator

        generator = SitemapGenerator()
        sitemaps = [
            "https://baixing-law.com/sitemap1.xml",
            "https://baixing-law.com/sitemap2.xml",
        ]

        xml = generator.generate_sitemap_index(sitemaps)

        assert '<?xml version="1.0"' in xml
        assert "sitemap1.xml" in xml
        assert "sitemap2.xml" in xml
        assert "<sitemapindex" in xml

    def test_get_page_list(self):
        """测试获取页面列表"""
        from app.services.seo import SitemapGenerator

        generator = SitemapGenerator()
        generator.add_page("/page1", "weekly", 0.5)
        generator.add_page("/page2", "daily", 0.8)

        pages = generator.get_page_list()

        assert len(pages) == 2


class TestMetaTagGenerator:
    """Meta 标签生成器测试"""

    def test_set_template(self):
        """测试设置模板"""
        from app.services.seo import MetaTagGenerator

        generator = MetaTagGenerator()
        generator.set_template(
            page_type="article",
            title="测试文章",
            description="文章描述",
            keywords=["法律", "咨询"],
            og_image="https://example.com/image.png",
        )

        assert "article" in generator._templates
        assert generator._templates["article"]["title"] == "测试文章"

    def test_generate_meta_tags(self):
        """测试生成 Meta 标签"""
        from app.services.seo import MetaTagGenerator

        generator = MetaTagGenerator()
        generator.set_template(
            page_type="article",
            title="测试文章",
            description="文章描述",
            keywords=["法律"],
        )

        tags = generator.generate_meta_tags("article")

        assert tags["title"] == "测试文章"
        assert tags["description"] == "文章描述"
        assert "法律" in tags["keywords"]
        assert tags["og:title"] == "测试文章"

    def test_generate_meta_tags_with_custom_override(self):
        """测试生成 Meta 标签（自定义覆盖）"""
        from app.services.seo import MetaTagGenerator

        generator = MetaTagGenerator()
        generator.set_template(
            page_type="article",
            title="原始标题",
            description="原始描述",
        )

        tags = generator.generate_meta_tags(
            "article",
            custom_title="自定义标题",
            custom_description="自定义描述",
        )

        assert tags["title"] == "自定义标题"
        assert tags["description"] == "自定义描述"

    def test_generate_meta_tags_with_params(self):
        """测试生成 Meta 标签（带额外参数）"""
        from app.services.seo import MetaTagGenerator

        generator = MetaTagGenerator()
        generator.set_template(
            page_type="article",
            title="基础标题",
            description="描述",
        )

        tags = generator.generate_meta_tags(
            "article",
            additional_params={"title_suffix": "百姓助手"},
        )

        assert "百姓助手" in tags["title"]

    def test_generate_meta_tags_with_user_name(self):
        """测试生成 Meta 标签（带用户名参数）"""
        from app.services.seo import MetaTagGenerator

        generator = MetaTagGenerator()
        generator.set_template(
            page_type="article",
            title="基础标题",
            description="描述",
        )

        tags = generator.generate_meta_tags(
            "article",
            additional_params={"user_name": "张三"},
        )

        assert "张三" in tags["title"]
        assert tags["title"] == "基础标题 - 张三"

    def test_generate_meta_tags_missing_template(self):
        """测试生成 Meta 标签（无模板）"""
        from app.services.seo import MetaTagGenerator

        generator = MetaTagGenerator()

        tags = generator.generate_meta_tags("unknown")

        assert tags["title"] == ""
        assert tags["description"] == ""

    def test_get_template(self):
        """测试获取模板"""
        from app.services.seo import MetaTagGenerator

        generator = MetaTagGenerator()
        generator.set_template("test", "标题", "描述", ["关键词"])

        template = generator.get_template("test")

        assert template is not None
        assert template["title"] == "标题"


class TestStructuredDataGenerator:
    """结构化数据生成器测试"""

    def test_generate_organization(self):
        """测试生成组织结构化数据"""
        from app.services.seo import StructuredDataGenerator

        generator = StructuredDataGenerator()
        data = generator.generate_organization()

        assert data["@context"] == "https://schema.org"
        assert data["@type"] == "LegalService"
        assert data["name"] == "百姓法律助手"
        assert "contactPoint" in data

    def test_generate_article(self):
        """测试生成文章结构化数据"""
        from app.services.seo import StructuredDataGenerator

        generator = StructuredDataGenerator()
        data = generator.generate_article(
            title="测试文章",
            description="文章描述",
            url="https://example.com/article",
            published_time="2024-01-01T00:00:00Z",
            author_name="作者",
            image="https://example.com/image.png",
        )

        assert data["@type"] == "Article"
        assert data["headline"] == "测试文章"
        assert "image" in data

    def test_generate_article_without_image(self):
        """测试生成文章结构化数据（无图片）"""
        from app.services.seo import StructuredDataGenerator

        generator = StructuredDataGenerator()
        data = generator.generate_article(
            title="测试文章",
            description="描述",
            url="https://example.com",
            published_time="2024-01-01",
            author_name="作者",
        )

        assert "image" not in data

    def test_generate_faq(self):
        """测试生成 FAQ 结构化数据"""
        from app.services.seo import StructuredDataGenerator

        generator = StructuredDataGenerator()
        data = generator.generate_faq([
            {"question": "问题1", "answer": "答案1"},
            {"question": "问题2", "answer": "答案2"},
        ])

        assert data["@type"] == "FAQPage"
        assert len(data["mainEntity"]) == 2
        assert data["mainEntity"][0]["@type"] == "Question"

    def test_generate_breadcrumb(self):
        """测试生成面包屑结构化数据"""
        from app.services.seo import StructuredDataGenerator

        generator = StructuredDataGenerator()
        data = generator.generate_breadcrumb([
            {"name": "首页", "url": "https://example.com"},
            {"name": "文章", "url": "https://example.com/articles"},
        ])

        assert data["@type"] == "BreadcrumbList"
        assert len(data["itemListElement"]) == 2
        assert data["itemListElement"][0]["position"] == 1

    def test_generate_jsonld(self):
        """测试生成 JSON-LD 字符串"""
        from app.services.seo import StructuredDataGenerator

        generator = StructuredDataGenerator()
        data = {"@type": "Test", "name": "测试"}
        jsonld = generator.generate_jsonld(data)

        assert '<script type="application/ld+json">' in jsonld
        assert '"name": "测试"' in jsonld


class TestSEOAnalyzer:
    """SEO 分析器测试"""

    @pytest.mark.asyncio
    async def test_analyze_page_excellent(self):
        """测试分析优秀页面"""
        from app.services.seo import SEOAnalyzer

        analyzer = SEOAnalyzer()
        result = await analyzer.analyze_page(
            url="https://example.com/article",
            title="这是一个很长的标题用于测试SEO优化效果",
            description="这是一个很长的描述用于测试SEO优化效果，确保长度在120-160字符之间以获得最佳效果",
            content="这是文章内容，应该包含足够的文字内容以满足SEO要求。" * 10,
            h1_count=1,
            image_count=3,
            link_count=5,
        )

        # 验证返回结果结构正确
        assert "score" in result
        assert "grade" in result
        assert "issues" in result
        assert "suggestions" in result
        # 验证分数合理
        assert result["score"] > 0

    @pytest.mark.asyncio
    async def test_analyze_page_good(self):
        """测试分析良好页面"""
        from app.services.seo import SEOAnalyzer

        analyzer = SEOAnalyzer()
        result = await analyzer.analyze_page(
            url="https://example.com/page",
            title="页面标题",
            description="页面描述",
            content="内容" * 200,
            h1_count=1,
            image_count=1,
            link_count=1,
        )

        assert result["grade"] in ["A", "B", "C"]

    @pytest.mark.asyncio
    async def test_analyze_page_title_too_long(self):
        """测试分析标题过长页面"""
        from app.services.seo import SEOAnalyzer

        analyzer = SEOAnalyzer()
        # 创建一个超过60个字符的标题（使用英文来精确控制长度）
        title = "This is a very very very very long title that exceeds sixty characters"
        result = await analyzer.analyze_page(
            url="https://example.com/page",
            title=title,
            description="This is a description that is valid length for SEO testing purposes and should not trigger warnings about being too short or long",
            content="word " * 100,
            h1_count=1,
            image_count=1,
            link_count=1,
        )

        # 验证返回结果结构正确
        assert "score" in result
        assert "issues" in result
        assert len(result["issues"]) > 0
        # 验证标题过长会添加问题和建议
        assert any("标题过长" in issue for issue in result["issues"])
        assert any("60 个字符" in suggestion for suggestion in result["suggestions"])
        # 验证标题长度超过60
        assert result["metrics"]["title_length"] > 60

