    @pytest.mark.asyncio
    async def test_analyze_page_description_optimal(self):
        """测试分析描述长度在120-160之间"""
        from app.services.seo import SEOAnalyzer

        analyzer = SEOAnalyzer()
        # 创建一个长度在120-160之间的英文描述（140个字符）
        description = "This is a well-optimized meta description that falls within the recommended 120-160 character range for best SEO performance and results."
        result = await analyzer.analyze_page(
            url="https://example.com/page",
            title="This is a medium length title for testing",
            description=description,
            content="word " * 100,
            h1_count=1,
            image_count=1,
            link_count=1,
        )

        # 验证描述长度在120-160之间时获得20分
        desc_len = result["metrics"]["description_length"]
        assert 120 <= desc_len <= 160
        assert result["score"] >= 20

